.ds .ds-token-leading { align-items:start; gap:var(--p-space-md); font-size:var(--p-text-body); }
.ds .ds-token-leading span { padding-inline:var(--p-space-xs); border-inline-start:var(--p-border-width-strong) solid var(--p-line); }
.ds .ds-token-leading [data-token="tight"] { line-height:var(--p-leading-tight); }
.ds .ds-token-leading [data-token="normal"] { line-height:var(--p-leading-normal); }
.ds .ds-token-leading [data-token="looser"] { line-height:var(--p-leading-looser); }
